BEGIN TRANSACTION;
CREATE TABLE excluded (
    item_id    TEXT NOT NULL,
    photo_id   TEXT NOT NULL,
    deleted_at REAL,
    PRIMARY KEY (item_id, photo_id)
);
CREATE TABLE files (
    id        TEXT PRIMARY KEY,   -- sha1(relpath|size|mtime)[:10]
    path      TEXT NOT NULL,
    kind      TEXT NOT NULL,      -- image | video | other
    size      INTEGER NOT NULL,
    status    TEXT NOT NULL DEFAULT 'scanned',  -- scanned | downscaled | error | skipped
    down_path TEXT,
    down_bytes INTEGER,
    width     INTEGER,
    height    INTEGER,
    sharp     REAL,
    lum       REAL,
    phash     TEXT,
    error     TEXT,
    updated   REAL
);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE slots (
    slot_key   TEXT PRIMARY KEY,          -- 'BR-001:1'
    item_id    TEXT NOT NULL,
    rank       INTEGER NOT NULL,
    photo_id   TEXT NOT NULL,
    status     TEXT NOT NULL DEFAULT 'pending',   -- pending | approved | rejected
    name       TEXT,
    rot        INTEGER NOT NULL DEFAULT 0,
    tilt       REAL NOT NULL DEFAULT 0,
    crop       TEXT,                      -- JSON [x0,y0,x1,y1] as fractions
    aspect     TEXT NOT NULL DEFAULT 'free',
    enhance    INTEGER NOT NULL DEFAULT 1,        -- decision: apply daylight enhancement?
    reviewed_at REAL,
    exported   INTEGER NOT NULL DEFAULT 0,        -- final/ file written for the current decision
    exported_enhanced INTEGER NOT NULL DEFAULT 0, -- that file was enhanced
    final_path TEXT,
    exported_at REAL
);
CREATE TABLE uploads (
    path        TEXT PRIMARY KEY,
    item_id     TEXT,                 -- parsed from the file name prefix (BR-001_...), when present
    brand       TEXT,
    bytes       INTEGER,
    width       INTEGER,
    height      INTEGER,
    recipe      TEXT,                 -- the exact enhancement recipe (JSON) used
    exported_at REAL
);
CREATE INDEX idx_files_status ON files(kind, status);
COMMIT;
